CREATE TABLE transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,idempotency_key text NOT NULL,payload_hash text NOT NULL,source_id uuid NOT NULL,destination_id uuid,amount bigint NOT NULL CHECK(amount>0),kind text NOT NULL CHECK(kind IN ('internal','external')),mode text NOT NULL DEFAULT 'success' CHECK(mode IN ('success','reject','timeout')),status text NOT NULL DEFAULT 'requested',error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
